import{z as s,x as A,o as t,c as B,q as r,j as n,D as e,d as E,s as l,S as d,b as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"牛顿迭代除法与倒数","description":"","frontmatter":{"title":"牛顿迭代除法与倒数","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/newton-division.md","filePath":"cs/newton-division.md","lastUpdated":1791063341000}'),p={name:"cs/newton-division.md"};function c(m,a,h,D,u,_){const i=A("Mermaid");return t(),B("div",null,[a[2]||(a[2]=r('<h1 id="牛顿迭代除法与倒数" tabindex="-1">牛顿迭代除法与倒数 <a class="header-anchor" href="#牛顿迭代除法与倒数" aria-label="Permalink to &quot;牛顿迭代除法与倒数&quot;">​</a></h1><div class="epigraph"><p>除法可以改成乘法：先迭代出倒数，再乘被除数；二次收敛让几次乘加就够用，前提是已有快速乘法器。</p><footer>—— 据 Ercegovac and Lang, Digital Arithmetic；IEEE Std 754-2008；Goldberg, What Every Computer Scientist Should Know about Floating-Point Arithmetic, 1991 整理</footer></div><p><a href="/cs/srt-division">上一课</a>用冗余数字把移位–减加快，仍是每步依赖余数的迭代加减。<a href="/cs/wallace-carry-save">华莱士树</a>已经把乘法变成浅组合（或浅流水）单元。缺口是：当乘法很便宜时，能否<strong>用乘来做除</strong>——牛顿求倒数，再乘。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>求 \\(1/d\\)。牛顿迭代解 \\(f(x)=1/x-d=0\\)，迭代 \\(x_{n+1}=x_n(2-d x_n)\\)，二次收敛：有效位数大约每步翻倍。初值来自查表（指数段 + 尾数高位）。缺口不是再写 SRT 表，而是另一条数据通路：几次乘加（或 FMA）换一次除。Goldschmidt（级数/连乘）是同一家族的变体，本课以牛顿钉方程，点名 Goldschmidt 为硬件上常见的并行乘实现。</p><p>浮点除还要对阶、舍入、异常；本课先钉倒数迭代的算术核，754 加法器在两课之后。</p><p><span class="marginnote">数字实例：除以 3——初值表给 \\(x_0\\approx0.333\\)；代入 \\(x_1=x_0(2-3x_0)=0.333\\times1.001\\approx0.3333\\)，正确位数大约翻倍。如此两三步就够到 double 的 53 位，全程只做乘加，没有一次除法。</span></p><h3 id="二次收敛不是「两次就精确」" tabindex="-1">二次收敛不是「两次就精确」 <a class="header-anchor" href="#二次收敛不是「两次就精确」" aria-label="Permalink to &quot;二次收敛不是「两次就精确」&quot;">​</a></h3><p>从 \\(k\\) 位近似到 \\(2k\\) 位，再 \\(4k\\)，直到超过目标格式精度，再按<a href="/cs/rounding-modes">舍入模式</a>收一次。中间乘必须用额外保护位，否则舍入误差会阻止最后 1 ulp 正确。把「牛顿除法」理解成软件里调两次 <code>mul</code> 就完，754 的正确舍入合同不成立。</p><p><span class="marginnote">754-2008 要求除法正确舍入到目标格式。硬件常用迭代乘 + 残差校正一步。Goldberg 1991 强调运算是格式上的函数，不是「多迭代几次随便截断」。</span></p><p><span class="marginnote">直觉类比：二次收敛像折纸——每折一次厚度翻倍。想要 53 位精度，从 8 位初值出发只需三折（8→16→32→64）；但中间乘的「保护位」就是折痕对齐，省了它最后一层永远差一点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><ol><li>查表得 \\(x_0\\approx 1/d\\)（尾数）。2. 重复 FMA：\\(x\\leftarrow x(2-dx)\\)，精度加倍。3. \\(q=n\\cdot x\\)，再算余数 \\(n-qd\\) 做一步校正，保证正确舍入。整数除也可先规格化除数再迭代，最后右移还原；许多 CPU 仍用 SRT 做整数，牛顿留给浮点。</li></ol>',13)),(t(),n(d,null,{default:e(()=>[l(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E9%99%A4%E6%95%B0%22%5D%20--%3E%20TAB%5B%22%E5%80%92%E6%95%B0%E5%88%9D%E5%80%BC%E8%A1%A8%22%5D%0A%20%20TAB%20--%3E%20IT%5B%22x(2-dx)%20%E8%BF%AD%E4%BB%A3%22%5D%0A%20%20IT%20--%3E%20MUL%5B%22%E8%A2%AB%E9%99%A4%E6%95%B0%E4%B9%98%E5%80%92%E6%95%B0%22%5D%0A%20%20MUL%20--%3E%20FIX%5B%22%E6%AE%8B%E5%B7%AE%E6%A0%A1%E6%AD%A3%E4%B8%8E%E8%88%8D%E5%85%A5%22%5D%0A%20%20FIX%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%B5%AE%E7%82%B9%E5%8A%A0%E6%B3%95%E5%99%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("p",null,"与 SRT 对照：SRT 的关键硬件是 CSA 与小表；牛顿的关键硬件是已有乘法器与稍大的初值 ROM。面积预算决定选哪条。",-1)),a[4]||(a[4]=o("h2",{id:"机制",tabindex:"-1"},[E("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=o("p",null,"后课浮点乘法/FMA 正是这条通路的引擎；本课预先承认：除法单元可以「几乎是乘法器加控制」。平方根有类似牛顿/Goldschmidt 迭代，本课不展开，以免把算术单元写成函数库。",-1)),(t(),n(d,null,{default:e(()=>[l(i,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20X0%5B%22x0%EF%BC%9A%E6%9F%A5%E8%A1%A8%E7%BA%A6%208%20%E4%BD%8D%E7%B2%BE%E5%BA%A6%22%5D%20--%3E%20S1%5B%22%E8%BF%AD%E4%BB%A3%201%20%E2%86%92%20%E7%BA%A6%2016%20%E4%BD%8D%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E8%BF%AD%E4%BB%A3%202%20%E2%86%92%20%E7%BA%A6%2032%20%E4%BD%8D%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E8%BF%AD%E4%BB%A3%203%20%E2%86%92%20%E7%BA%A6%2064%20%E4%BD%8D%22%5D%0A%20%20S3%20--%3E%20CMP%7B%22%E4%BD%8D%E6%95%B0%20%5Cgt%20%E7%9B%AE%E6%A0%87%E6%A0%BC%E5%BC%8F%EF%BC%9F%22%7D%0A%20%20CMP%20--%3E%7C%22%E5%90%A6%22%7C%20S2%0A%20%20CMP%20--%3E%7C%22%E6%98%AF%22%7C%20FIX%5B%22%E4%B9%98%E8%A2%AB%E9%99%A4%E6%95%B0%20%2B%20%E6%AE%8B%E5%B7%AE%E6%A0%A1%E6%AD%A3%E4%B8%8E%E8%88%8D%E5%85%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>这张图回答：二次收敛怎么折算成迭代次数。有效位数每步翻倍，从查表初值到 double 的 53 位只要约三次 FMA；到位后仍要做一步残差校正，直接停手截断就够不到正确舍入。</p><p><span class="marginnote">常见误区：初学者容易把「二次收敛」读成「两次迭代就精确」。它说的是有效位数每步翻倍——从 4 位到 64 位要走 4 步；而且最后必须残差校正一次，否则 754 的正确舍入合同不成立。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明二次收敛的区间，不给初值表的具体比特。不把软件 <code>libm</code> 的 Newton 当 CPU 除法器。也不进入「训练里的近似倒数指令」（GPU <code>__frcp</code>）——那是精度更低的特化，不是 754 除。</p><p>后课默认：倒数可由牛顿/Goldschmidt 迭代得到；精确除还要残差校正；浮点加减是下一条缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SRT 走移位减；牛顿走乘：先 \\(1/d\\) 再乘。</li><li>二次收敛，初值查表，最后校正才能正确舍入。</li><li>依赖快速乘法器，与华莱士树配套。</li><li>出处：Ercegovac and Lang；IEEE 754-2008；Goldberg, 1991。</li></ul>',7))])}const S=s(p,[["render",c]]);export{f as __pageData,S as default};
